    name = "world";

console.log(greet, name);

let hello = "hello,",
    world = "world";

console.log(hello, world);

var greet = "hello,";
const NAME = "world";

console.log(greet, NAME);

var greet = "hello,";
var name = "world";
// var name = require("world");

console.log(greet, name);
```

### never

Examples of incorrect code for this rule with the `"never"` option:


```json
/*eslint newline-after-var: ["error", "never"]*/
/*eslint-env es6*/

