function callback() {
    // ...
}

element.callback = function() {
    // ...
};

var itemSet = {
    data: [...values]
};

class Foo {
    data = [];
}

class Bar {
    #data = [];
}

class Baz {
    callback() {}
}

class Qux {
    #callback() {}
}
```

Examples of correct code for this rule with sample `"data", "callback"` restricted identifiers:


```json
/*eslint id-denylist: ["error", "data", "callback"] */

